fn lock_until<'a,T>(mutex:&'a Mutex<T>,deadline:Instant,label:&str)->Result<std::sync::MutexGuard<'a,T>,String>{loop{if Instant::now()>=deadline{return Err(format!("{label} timed out; outcome unconfirmed"))}match mutex.try_lock(){Ok(g)=>return Ok(g),Err(std::sync::TryLockError::Poisoned(_))=>return Err(format!("{label} poisoned; outcome unconfirmed")),Err(std::sync::TryLockError::WouldBlock)=>{if Instant::now()>=deadline{return Err(format!("{label} timed out; outcome unconfirmed"))}std::thread::sleep(Duration::from_millis(5));}}}}
fn remaining(deadline:Instant)->Duration{deadline.saturating_duration_since(Instant::now())}
struct Trace{tx:std::sync::mpsc::SyncSender<String>,rx:Mutex<std::sync::mpsc::Receiver<String>>,lost:AtomicBool}
impl Trace{fn new()->Self{let(tx,rx)=std::sync::mpsc::sync_channel(128);Self{tx,rx:Mutex::new(rx),lost:AtomicBool::new(false)}}fn record(&self,name:&str,value:&Value){let Some(n)=value.as_i64()else{self.lost.store(true,Ordering::Release);return};if self.tx.try_send(format!("{name}:{n}")).is_err(){self.lost.store(true,Ordering::Release)}}fn snapshot(&self)->Result<Vec<String>,String>{if self.lost.load(Ordering::Acquire){return Err("fixture diagnostics lost".into())}self.rx.try_lock().map(|rx|rx.try_iter().collect()).map_err(|_|"fixture diagnostics unavailable".into())}}
