 pub fn connect_database(&self,payload:Option<Value>)->Result<Value,String>{
  self.context.replace(Duration::from_secs(100),|time|self.scheduler.quiesce(time),|time|self.background.stop(time),||{
   #[cfg(feature="pg80-owned-observe")] {self.init_pid.store(0,Ordering::Release);self.probe_pid.store(0,Ordering::Release);}
   let config=match payload {Some(v) if !v.is_null()=>v,_=>self.settings_load()?.get("database").cloned().ok_or("owned database settings missing")?};self.authority.validate_database_settings(&config)?;self.authority.connect_read_only()
  },|time|self.scheduler.resume(time))?;Ok(Value::Null)
 }
 pub fn disconnect_database(&self)->Result<Value,String>{self.context.disconnect(Duration::from_secs(100),|time|self.scheduler.quiesce(time),|time|self.background.stop(time))?;Ok(Value::Null)}
