 pub fn initialize(&self)->Result<Value,String>{let _gate=lock_until(&self.context.init_admission,Instant::now()+Duration::from_secs(100),"initialization admission")?;#[cfg(feature="pg80-owned-observe")] {self.init_pid.store(0,Ordering::Release);self.init_evidence.try_lock().map_err(|_|"initialization evidence unavailable")?.take();}if self.context.stopping.load(Ordering::Acquire){return Err("fixture stopping".into())}super::initialize_pg79_live_analysis(self)}
